import json
with open('/app/resources/treasury_bulletin_1953_03.json') as f:
    data = json.load(f)

# Search all text in the JSON for '12/18' or similar
def search(obj, path='', depth=0):
    if depth > 5:
        return
    if isinstance(obj, str):
        if '12/18' in obj:
            print(f'{path}: {obj}')
    elif isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]', depth+1)

search(data)
"
